/// <summary>
/// MPJ_5583_Fixed asset transations
/// </summary>
[ExtensionOf(tableStr(AssetTrans))]
final class METAssetTrans_Extension
{
}

Method.Source:
    /// <summary>
    /// MPJ_5583_Fixed asset transations
    /// </summary>
    /// <param name = "assetTrans"> 
    /// get the table buffer of assetTrans
    /// </param>
    /// <returns>
    /// return proj id related to the asset 
    /// </returns>
    static display ProjId getMETProjId(AssetTrans metAssetTrans)
    {
        AssetTable  metAssetTable;
        ProjTable   metProjTable;
        ProjId      METWBSElement;

        select firstonly AssetId from metAssetTrans
            join AssetId from metAssetTable
        where metAssetTable.AssetId == metAssetTrans.AssetId
            join AssetId from  metProjTable
        where metProjTable.AssetId == metAssetTable.AssetId;

        METWBSElement = metProjTable.ProjId;
        return METWBSElement;

    }

    /// <summary>
    /// MPJ_5583_Fixed asset transations
    /// </summary>
    /// <param name = "metAssetTrans">
    /// get the table buffer
    /// </param>
    /// <returns>
    /// return Depreciation value 
    /// </returns>
    static display AssetAmountReportingCurrency metActualDepreciationValueReportingCurrency(AssetTrans metAssetTrans)
    {
        AssetSumCalc    metAssetSumTransReportingCurrency;

        metAssetSumTransReportingCurrency = AssetSumCalc_Trans::newAssetYear
                                            (metAssetTrans.AssetId, metAssetTrans.BookId,
                                             DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone()),
                                             AssetYear::ThisYear);

        return  metAssetSumTransReportingCurrency.depreciationValue();

    }

    /// <summary>
    /// MPJ_5583_Fixed asset transations
    /// </summary>
    /// <param name = "metAssetTrans">
    /// get the table buffer
    /// </param>
    /// <returns>
    /// return Depreciation Value
    /// </returns>
    static display  AssetDepreciation metAssetValuationDepreciationValueReportingCurrency(AssetTrans    metAssetTrans)
    {
        AssetSumCalc    metAssetSumCalcReporting;

        metAssetSumCalcReporting = AssetSumCalc_Trans::newAssetYearByCurrency
                                    (metAssetTrans.AssetId, metAssetTrans.BookId, 
                                      DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone()),
                                      assetYear::All, AssetSumCalcType::Reporting);
        if (metAssetSumCalcReporting)
        {
            return metAssetSumCalcReporting.depreciationValue();
        }
        else
        {
            return 0;
        }
    }
